-- ============================================================================
-- EcoApartment OS: PostgreSQL / Supabase Complete Database Schema & Seed
-- Target: SRM Green Residency (Blocks A, B, C, D | 400 Flats)
-- Includes: DDL, Indexes, Row Level Security (RLS) Policies, Triggers & Seed Data
-- ============================================================================

-- Enable UUID extension
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";

-- 1. USERS & RESIDENT PROFILES (400 Flats)
CREATE TABLE IF NOT EXISTS residents (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    username TEXT UNIQUE NOT NULL,
    password_hash TEXT NOT NULL,
    role TEXT NOT NULL DEFAULT 'RESIDENT' CHECK (role IN ('AUTHORITY', 'RESIDENT', 'TECHNICIAN')),
    block TEXT NOT NULL CHECK (block IN ('A', 'B', 'C', 'D')),
    floor_number INTEGER NOT NULL CHECK (floor_number BETWEEN 0 AND 4),
    flat_number TEXT UNIQUE NOT NULL,
    resident_name TEXT NOT NULL,
    contact_number TEXT NOT NULL,
    email TEXT DEFAULT '',
    occupancy_status TEXT NOT NULL DEFAULT 'OCCUPIED' CHECK (occupancy_status IN ('OCCUPIED', 'VACANT', 'MAINTENANCE')),
    move_in_date DATE DEFAULT CURRENT_DATE,
    emergency_contact TEXT DEFAULT '+91 98401 00000',
    vehicle_number TEXT DEFAULT '',
    dues_status TEXT NOT NULL DEFAULT 'PAID' CHECK (dues_status IN ('PAID', 'PENDING', 'OVERDUE')),
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- 2. COMPLAINTS & HELPDESK TICKETS
CREATE TABLE IF NOT EXISTS complaints (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    ticket_id TEXT UNIQUE NOT NULL,
    flat_number TEXT NOT NULL,
    floor_number INTEGER NOT NULL,
    category TEXT NOT NULL CHECK (category IN ('PLUMBING', 'ELECTRICAL', 'GAS_SUPPLY', 'ELEVATOR', 'CIVIL', 'CLEANLINESS', 'SECURITY')),
    priority TEXT NOT NULL DEFAULT 'STANDARD' CHECK (priority IN ('STANDARD', 'URGENT', 'CRITICAL')),
    description TEXT NOT NULL,
    status TEXT NOT NULL DEFAULT 'OPEN' CHECK (status IN ('OPEN', 'ASSIGNED', 'IN_PROGRESS', 'RESOLVED')),
    authority_notes TEXT DEFAULT '',
    assigned_technician TEXT DEFAULT 'General Maintenance Team',
    work_log TEXT DEFAULT '',
    raised_by_name TEXT NOT NULL,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- 3. MAINTENANCE DUES & BILLING
CREATE TABLE IF NOT EXISTS maintenance_dues (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    due_id TEXT UNIQUE NOT NULL,
    flat_number TEXT NOT NULL,
    month_year TEXT NOT NULL,
    amount_rupees NUMERIC(10, 2) NOT NULL,
    due_date DATE NOT NULL,
    status TEXT NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PAID', 'PENDING', 'OVERDUE')),
    paid_date TIMESTAMPTZ,
    payment_method TEXT DEFAULT '',
    transaction_ref TEXT DEFAULT '',
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 4. COMMUNITY NOTICES
CREATE TABLE IF NOT EXISTS community_notices (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    title TEXT NOT NULL,
    description TEXT NOT NULL,
    category TEXT NOT NULL CHECK (category IN ('WATER', 'GREEN_ENERGY', 'SAFETY', 'MAINTENANCE', 'GENERAL')),
    priority TEXT NOT NULL DEFAULT 'NORMAL' CHECK (priority IN ('NORMAL', 'HIGH', 'URGENT')),
    posted_time TEXT NOT NULL,
    is_pinned BOOLEAN DEFAULT FALSE,
    author TEXT DEFAULT 'Facility Office',
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 5. VISITOR MANAGEMENT & GATE PASSES
CREATE TABLE IF NOT EXISTS visitors (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    visitor_code TEXT UNIQUE NOT NULL,
    name TEXT NOT NULL,
    phone TEXT NOT NULL,
    visitor_type TEXT NOT NULL CHECK (visitor_type IN ('GUEST', 'DELIVERY', 'CAB', 'SERVICE')),
    flat_number TEXT NOT NULL,
    floor_number INTEGER NOT NULL,
    vehicle_number TEXT DEFAULT '',
    purpose TEXT NOT NULL,
    entry_time TEXT NOT NULL,
    approval_status TEXT NOT NULL DEFAULT 'APPROVED' CHECK (approval_status IN ('APPROVED', 'CHECKED_IN', 'CHECKED_OUT', 'PENDING', 'REJECTED')),
    approved_by TEXT NOT NULL,
    pass_code TEXT NOT NULL,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 6. WATER ANOMALY DETECTION ENGINE LOGS
CREATE TABLE IF NOT EXISTS water_anomalies (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    sensor_id TEXT NOT NULL,
    zone_id TEXT NOT NULL,
    flow_rate NUMERIC(6, 2) NOT NULL,
    threshold NUMERIC(6, 2) NOT NULL,
    status TEXT NOT NULL DEFAULT 'ACTIVE_ALERT',
    detected_at TIMESTAMPTZ DEFAULT NOW(),
    notes TEXT DEFAULT ''
);

-- INDEXES
CREATE INDEX IF NOT EXISTS idx_residents_flat ON residents(flat_number);
CREATE INDEX IF NOT EXISTS idx_residents_block_floor ON residents(block, floor_number);
CREATE INDEX IF NOT EXISTS idx_residents_occupancy ON residents(occupancy_status);
CREATE INDEX IF NOT EXISTS idx_complaints_flat ON complaints(flat_number);
CREATE INDEX IF NOT EXISTS idx_complaints_status ON complaints(status);
CREATE INDEX IF NOT EXISTS idx_dues_flat ON maintenance_dues(flat_number);
CREATE INDEX IF NOT EXISTS idx_dues_status ON maintenance_dues(status);

-- ROW LEVEL SECURITY (RLS) POLICIES
ALTER TABLE residents ENABLE ROW LEVEL SECURITY;
ALTER TABLE complaints ENABLE ROW LEVEL SECURITY;
ALTER TABLE maintenance_dues ENABLE ROW LEVEL SECURITY;
ALTER TABLE community_notices ENABLE ROW LEVEL SECURITY;
ALTER TABLE visitors ENABLE ROW LEVEL SECURITY;
ALTER TABLE water_anomalies ENABLE ROW LEVEL SECURITY;

-- Anonymous and Authenticated read policies
CREATE POLICY "Public read for community notices" ON community_notices FOR SELECT USING (true);
CREATE POLICY "Allow authenticated users to read residents" ON residents FOR SELECT USING (true);
CREATE POLICY "Allow admins full access to residents" ON residents FOR ALL USING (true);
CREATE POLICY "Allow authenticated users to view complaints" ON complaints FOR SELECT USING (true);
CREATE POLICY "Allow residents to insert complaints" ON complaints FOR INSERT WITH CHECK (true);
CREATE POLICY "Allow updates to complaints" ON complaints FOR UPDATE USING (true);
CREATE POLICY "Allow read dues" ON maintenance_dues FOR SELECT USING (true);
CREATE POLICY "Allow dues payments" ON maintenance_dues FOR UPDATE USING (true);
CREATE POLICY "Allow visitor passes management" ON visitors FOR ALL USING (true);
CREATE POLICY "Allow water anomalies logging" ON water_anomalies FOR ALL USING (true);

-- ============================================================================
-- SEED DATA (SRM Green Residency 400 Flats + Preserved Legacy Records)
-- ============================================================================

-- Inserting 400 flats and authority accounts
ON CONFLICT (flat_number) DO NOTHING;

-- Inserting Complaints
ON CONFLICT (ticket_id) DO NOTHING;

-- Inserting Community Notices

-- Inserting Maintenance Dues
ON CONFLICT (due_id) DO NOTHING;

